CLOSURE_CHECKS_CLASSIFIER_AUDIT: {
  "schema_version": 1,
  "migration_run_id": "498a2d27-37d7-49ee-9cf9-4d877f633f1c",
  "snapshot_timestamp": "2026-05-21T17:06:43Z",
  "ticket_id": "f7d5-59e4",
  "items": [
    {
      "original_text": "For each task generated by /dso:implementation-plan, ref-library-loader.sh annotates the task with up to 6 relevant reference citations drawn from the merged corpus+URL reference set (headroom from merged-set cap of 20 allows LLM relevance judgment to select top 6); tasks with no relevant matches (merged set empty after LLM judgment excludes all candidates) are generated without citations and no error is raised. The \"6\" constant is documented in ref-library-loader.sh as `MAX_CITATIONS_PER_TASK=6`.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability where tasks are annotated with citations according to a defined mechanism and constant"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Two citation formats supported and visually distinguishable in task output: URL-sourced `> Reference: [Doc Title](url) \u2014 [one-sentence excerpt]` and corpus-sourced `> Reference: [Doc Title] (dso:ui-reference:<entry-id>) \u2014 [one-sentence excerpt]`.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system capability of supporting and displaying two citation formats distinctly in task output"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "ref-library-loader.sh pipeline (per task): (a) query local UI/UX corpus via `dso ref-query --top-n=8` using task title+description with 30s subprocess timeout and explicit PID tracking (no zombie processes); (b) apply topic-tag substring filter to configured URL references, fetch via `confluence-fetch.sh`, cap post-filter set at 12 with consistent budget accounting (failed fetches excluded, retry quota re-filled from next candidate to maintain target budget); (c) merge both sets with local-first precedence \u2014 corpus entries preserved; URL slots expand to fill unused corpus budget ONLY when corpus returns fewer than 8 AND merged-set cap of 20 has remaining capacity (explicit slot-reallocation documented); (d) LLM relevance judgment per-entry with UTF-8-safe 200-character excerpt truncation at character boundary, concurrent-invocation cap of 3; (e) select top 6 entries by LLM relevance score for citation annotation.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system capability (ref-library-loader pipeline behavior with specific query, filtering, merging, and ranking steps) that persists after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Topic-tag filter with no configured tags defaults to match-none semantics (URL references with empty tags field excluded from filter output) \u2014 documented default. URL references with explicit tags use substring matching against task title and description.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes durable system behavior and filtering semantics that persist after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Runtime guards: (a) `command -v dso ref-query` at startup; absent \u2192 stderr warning, URL-only mode; (b) `command -v confluence-fetch.sh` at startup; absent \u2192 stderr warning, corpus-only mode; (c) missing `confluence.base_url` key \u2192 configuration error at startup, URL fetch path aborts, corpus-only mode with clear stderr error; (d) BOTH unavailable \u2192 stderr warning, tasks generated without citations, no error.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable runtime behaviors and fallback modes that the system will exhibit based on guard conditions, phrased as ongoing system properties"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Integration test suite at tests/integration/test-ref-library-loader-integration.sh validates: (a) corpus-only mode returns corpus-sourced citations; (b) URL-only mode returns URL-sourced citations; (c) merge mode returns both formats with verified local-first precedence; (d) sparse corpus (ref-query returns 3 entries) reallocates up to 5 URL slots without crowd-out; (e) both-unavailable mode generates tasks without citations and no error; (f) UTF-8 multibyte characters in excerpts never split mid-codepoint.",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable validation behavior of an integration test suite that continuously verifies system properties across multiple modes and edge cases"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Validation signal (executable within sprint): Before/after comparison on exactly 3 representative implementation-plan tasks drawn from recent org work. Baseline (ref-library-loader inactive) vs. treatment (ref-library-loader active). Pass threshold: ALL 3 treatment tasks must cite at least one Confluence or corpus source (URL-sourced or corpus-sourced format) that is ABSENT from the corresponding baseline task's generated output, verified by string comparison of the full annotated vs. unannotated task body (citation lines grep'd on prefix `> Reference:`). Any of the 3 comparisons failing this check fails the validation signal and blocks sprint closure.",
      "original_section": "SC",
      "classification": {
        "label": "transitional",
        "ranking": 4,
        "rationale": "describes a one-time validation check with specific pass/fail criteria that determines sprint closure, not an ongoing system property"
      },
      "user_decision": "accept",
      "post_migration_section": "CC"
    }
  ]
}
